import bisect

def fewest_checks(jobs):
    marks = []
    for start, end, need in sorted(jobs, key=lambda job: (job[1], -job[0])):
        have = bisect.bisect_right(marks, end) - bisect.bisect_left(marks, start)
        for minute in range(end, end - (need - have), -1):
            bisect.insort(marks, minute)
    return len(marks)

def fewest_checks(jobs):
    marks = []
    for start, end, need in sorted(jobs, key=lambda job: (job[1], -job[0])):
        if not any(start <= m <= end for m in marks):
            marks.extend(range(end, end - need, -1))
    return len(marks)
